import{_ as a,o,c as t,ag as r}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Portable Form Host APIs","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/index.md","filePath":"spec/host-api/index.md"}'),i={name:"spec/host-api/index.md"};function s(n,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="portable-form-host-apis" tabindex="-1">Portable Form Host APIs <a class="header-anchor" href="#portable-form-host-apis" aria-label="Permalink to &quot;Portable Form Host APIs&quot;">​</a></h1><h2 id="beta-2-design-target-host-api-v1beta2" tabindex="-1">Beta 2 design target: Host API v1beta2 <a class="header-anchor" href="#beta-2-design-target-host-api-v1beta2" aria-label="Permalink to &quot;Beta 2 design target: Host API v1beta2&quot;">​</a></h2><p><code>forms.takoform.com/v1beta2</code> (<a href="./v1beta2.html"><code>v1beta2.md</code></a>) is the Beta 2 generation&#39;s lane, minted for protocol reasons out of the hardening review (decisions <a href="./../decisions/0039-a-lane-is-minted-for-one-of-two-reasons.html">0039</a>, <a href="./../decisions/0046-stable-arrives-through-a-stable-grade-beta-2.html">0046</a>):</p><ul><li>discovery: <code>GET /.well-known/takoform/v1beta2</code>;</li><li>API root: <code>/apis/forms.takoform.com/v1beta2</code>;</li><li>wire schema: <a href="/schemas/v1beta2/host-api-wire.schema.json"><code>host-api-wire-v1beta2.schema.json</code></a>;</li><li>operation table: <a href="operations-v1beta2.json"><code>operations-v1beta2.json</code></a>.</li></ul><p>No released provider speaks it yet; the 3.0.0 release will. Until then the published current lane below keeps its meaning unchanged.</p><h2 id="current-published-lane-host-api-v1beta1" tabindex="-1">Current published lane: Host API v1beta1 <a class="header-anchor" href="#current-published-lane-host-api-v1beta1" aria-label="Permalink to &quot;Current published lane: Host API v1beta1&quot;">​</a></h2><p>The lane published provider <code>v2.1.1</code> speaks is the literal <code>forms.takoform.com/v1beta1</code> <strong>Host API</strong> (<a href="./v1beta1.html"><code>v1beta1.md</code></a>), a Beta protocol channel with its own discovery and operation documents:</p><ul><li>discovery: <code>GET /.well-known/takoform/v1beta1</code>;</li><li>API root: <code>/apis/forms.takoform.com/v1beta1</code>;</li><li>wire schema: <a href="/schemas/v1beta1/host-api-wire.schema.json"><code>host-api-wire-v1beta1.schema.json</code></a>;</li><li>operation table: <a href="operations-v1beta1.json"><code>operations-v1beta1.json</code></a>.</li></ul><p>Human Provider 2.1.1 is the Registry-published stable-distribution SemVer that carries this protocol. <code>release/version.json</code> intentionally remains <code>publicationStatus: candidate-only</code> descriptor metadata after owner publication; the retained signed Registry readback is the Provider availability evidence. The Beta label here belongs to the Host API, not to Provider 2.1.1 (<a href="./../decisions/0035-beta-contracts-ship-in-stable-provider-v2-1.html">decision 0035</a>).</p><p>The current protocol serves the literal Edge Form Family <code>edge.forms.takoform.com/v1beta1</code>: 15 individual <code>0.1.0</code> Form definitions, each Experimental. Their current Form Package envelope is the literal <code>packages.forms.takoform.com/v1alpha4</code>; package artifacts remain unpublished. The nested <code>interfaces.takoform.com/v1alpha1</code> and <code>bindings.takoform.com/v1alpha1</code> identifiers are independent contracts, not Host API maturity labels.</p><p>For the complete current contract, read <a href="./v1beta1.html"><code>v1beta1.md</code></a>. Requirement keywords are used as described in <a href="./../conformance.html"><code>../conformance.md</code></a>, and the digest-pinned conformance input for any neutral black-box host runner is <a href="../../conformance/portable-host-v1beta1/contract.json"><code>conformance/portable-host-v1beta1/contract.json</code></a>.</p><h2 id="withdrawn-pre-beta-lanes" tabindex="-1">Withdrawn pre-Beta lanes <a class="header-anchor" href="#withdrawn-pre-beta-lanes" aria-label="Permalink to &quot;Withdrawn pre-Beta lanes&quot;">​</a></h2><p>Three earlier Host API lanes existed and were withdrawn with their epochs (<a href="./../decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>):</p><ul><li><code>forms.takoform.com/v1alpha1</code>, the Legacy provider-v1 lane at the unversioned <code>/.well-known/takoform</code>;</li><li><code>forms.takoform.com/v1alpha2</code>, the provider-v2 lane at <code>/.well-known/takoform/v1alpha2</code>;</li><li><code>forms.takoform.com/v1alpha3</code>, whose wire the v1beta1 lane carried forward (<a href="./../decisions/0038-a-generation-move-is-measured-not-assumed.html">decision 0038</a>).</li></ul><p>Their normative documents, operation tables, and wire schemas are recorded as retired identities in <a href="../../release/published-document-lanes.json"><code>release/published-document-lanes.json</code></a> and remain readable in this repository&#39;s git history. A withdrawn lane identifier is never reused for a different contract, and published provider releases that speak those lanes (<code>v1.0.3</code>, <code>v2.0.0</code>) remain immutable Registry history. A host has no obligation to keep serving a withdrawn lane; a client that needs one pins the provider release that speaks it and the history that defines it.</p>',15)])])}const b=a(i,[["render",s]]);export{m as __pageData,b as default};
